//! Joule-Thomson inversion comparisons against the exact-source library.
//! Generated by tools/rust_port/validate_joule_thompson.py.
//! Copyright thermotools and Contributors. Apache-2.0.

#![allow(clippy::excessive_precision)]

use thermopack_rs::Cubic;
use thermopack_rs::CubicKind;

const ATOL: [f64; 2] = [1.0e-6, 1.0e-4];
const RTOL: f64 = 1.0e-7;

#[test]
fn inversion_points_match_the_source() {
    let mut checked = 0;
    for row in include_str!("fixtures/joule_thompson.csv").lines().skip(1) {
        let fields: Vec<_> = row.split(';').collect();
        let case = fields[0];
        let parts: Vec<_> = case.split('|').collect();
        let kind = match parts[0] {
            "SRK" => CubicKind::SoaveRedlichKwong,
            "RK" => CubicKind::RedlichKwong,
            "VDW" => CubicKind::VanDerWaals,
            _ => CubicKind::PengRobinson,
        };
        let components: Vec<&str> = parts[1].split(',').collect();
        let source_temperature: f64 = fields[1].parse().unwrap();
        let source_pressure: f64 = fields[2].parse().unwrap();
        let model = Cubic::new(kind, &components).unwrap();
        let composition = vec![1.0; components.len()];
        // The volume of the point follows from the pressure and the
        // temperature of the source, and the native solve starts from a
        // perturbed temperature.
        let volume = volume_of(&model, source_temperature, source_pressure, &composition);
        let guess = source_temperature * 1.02;
        let point =
            thermopack_rs::joule_thompson::inversion_point(&model, volume, guess, &composition)
                .unwrap();
        for (position, (source, native)) in [
            (source_temperature, point.temperature),
            (source_pressure, point.pressure),
        ]
        .iter()
        .enumerate()
        {
            assert!(
                (source - native).abs() <= ATOL[position] + RTOL * source.abs(),
                "{case} {}: source {source} native {native}",
                ["temperature", "pressure"][position]
            );
        }
        checked += 1;
    }
    assert!(checked > 70);
}

#[test]
fn the_inversion_condition_vanishes() {
    // The inversion condition of the original vanishes at the solution.
    let model = Cubic::new(CubicKind::PengRobinson, &["N2"]).unwrap();
    let volume = 0.5;
    let point =
        thermopack_rs::joule_thompson::inversion_point(&model, volume, 650.0, &[1.0]).unwrap();
    let state = model.prepare(point.temperature, &[1.0]).unwrap();
    let pressure = state.pressure(volume).unwrap();
    let residual = point.temperature * pressure.dt + volume * pressure.dv;
    let scale = (point.temperature * pressure.dt).abs() + (volume * pressure.dv).abs();
    assert!(residual.abs() < 1.0e-9 * scale, "{residual}");
}

#[test]
fn the_inversion_solve_recovers_the_solution() {
    // A perturbed initial guess must reach the same solution.
    let model = Cubic::new(CubicKind::PengRobinson, &["N2"]).unwrap();
    let reference =
        thermopack_rs::joule_thompson::inversion_point(&model, 0.5, 650.0, &[1.0]).unwrap();
    for guess in [600.0, 620.0, 660.0, 700.0] {
        let point =
            thermopack_rs::joule_thompson::inversion_point(&model, 0.5, guess, &[1.0]).unwrap();
        assert!(
            (point.temperature - reference.temperature).abs() < 1.0e-6,
            "{guess}"
        );
    }
}

/// The molar volume of a state from its temperature and its pressure.
fn volume_of(model: &Cubic, temperature: f64, pressure: f64, composition: &[f64]) -> f64 {
    let state = model.prepare(temperature, composition).unwrap();
    state.volume(pressure, thermopack_rs::Phase::Vapor).unwrap()
}
